//! Bounded declarative Rust macro expansion for documentation. Only explicitly
//! selected, local, single-rule templates with comma-separated ident/literal
//! parameters are accepted. Unsupported syntax is a diagnostic, not omission.
use anyhow::{Result, bail};
use serde::Serialize;
use std::collections::BTreeMap;
use tree_sitter::{Node, Parser};

/// Source generated by one selected macro invocation, with its original location.
#[derive(Debug, Clone, Serialize)]
pub struct Expansion {
    /// Expanded Rust items, retaining attributes and declaration bodies.
    pub source: String,
    /// One-based invocation line in the original file.
    pub line: usize,
}
/// Descendant metavariable substitutions in a template. Strings/comments are
/// leaves, so text that merely mentions a parameter is never substituted.
fn replacements(
    node: Node<'_>,
    source: &str,
    args: &BTreeMap<String, String>,
    out: &mut Vec<(usize, usize, String)>,
) -> Result<()> {
    if matches!(node.kind(), "token_repetition" | "token_repetition_pattern") {
        bail!("macro repetition is unsupported");
    }
    if node.kind() == "metavariable" {
        let name = &source[node.byte_range()];
        let value = args
            .get(name)
            .ok_or_else(|| anyhow::anyhow!("unbound macro parameter {name}"))?;
        out.push((node.start_byte(), node.end_byte(), value.clone()));
        return Ok(());
    }
    let mut cursor = node.walk();
    for child in node.named_children(&mut cursor) {
        replacements(child, source, args, out)?;
    }
    Ok(())
}
/// Every node in source order, including the root.
fn nodes<'a>(node: Node<'a>, out: &mut Vec<Node<'a>>) {
    out.push(node);
    let mut cursor = node.walk();
    for child in node.named_children(&mut cursor) {
        nodes(child, out);
    }
}
/// Expand selected macro calls in this file using their one local template.
/// Missing templates, ambiguous rules and unmatched arguments are failures.
pub(super) fn expand(
    source: &str,
    selected: &[String],
    ignored: &[String],
    strict: bool,
) -> Result<Vec<Expansion>> {
    if selected.is_empty() && !strict {
        return Ok(Vec::new());
    }
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_rust::LANGUAGE.into())?;
    let tree = parser
        .parse(source, None)
        .ok_or_else(|| anyhow::anyhow!("macro parser returned no tree"))?;
    let mut all = Vec::new();
    nodes(tree.root_node(), &mut all);
    let text = |node: Node<'_>| &source[node.byte_range()];
    let mut templates = BTreeMap::new();
    for definition in all.iter().filter(|n| n.kind() == "macro_definition") {
        let Some(name) = definition.child_by_field_name("name") else {
            continue;
        };
        if !selected.iter().any(|s| s == text(name)) {
            continue;
        }
        let mut cursor = definition.walk();
        let rules: Vec<_> = definition
            .named_children(&mut cursor)
            .filter(|n| n.kind() == "macro_rule")
            .collect();
        if rules.len() != 1 {
            bail!("selected macro {} must have exactly one rule", text(name));
        }
        let pattern = rules[0].child_by_field_name("left").unwrap();
        let body = rules[0].child_by_field_name("right").unwrap();
        let mut parameters = Vec::new();
        let mut cursor = pattern.walk();
        for child in pattern.named_children(&mut cursor) {
            if child.kind() != "token_binding_pattern" {
                bail!(
                    "selected macro {} only supports ident/literal parameters",
                    text(name)
                );
            }
            let variable = child.child_by_field_name("name").unwrap();
            let kind = child.child_by_field_name("type").unwrap();
            if !matches!(text(kind), "ident" | "literal") {
                bail!(
                    "selected macro {} unsupported fragment {}",
                    text(name),
                    text(kind)
                );
            }
            parameters.push((text(variable).to_string(), text(kind).to_string()));
        }
        // The matcher may contain commas and delimiters, not literal tokens.
        let mut stripped = text(pattern).to_string();
        let mut cursor = pattern.walk();
        let bindings: Vec<_> = pattern.named_children(&mut cursor).collect();
        for child in bindings.iter().rev() {
            stripped.replace_range(
                child.start_byte() - pattern.start_byte()..child.end_byte() - pattern.start_byte(),
                "",
            );
        }
        if stripped
            .chars()
            .any(|c| !c.is_whitespace() && !matches!(c, '(' | ')' | '[' | ']' | '{' | '}' | ','))
        {
            bail!("selected macro {} has an unsupported matcher", text(name));
        }
        if templates
            .insert(text(name).to_string(), (parameters, body))
            .is_some()
        {
            bail!("duplicate selected macro {}", text(name));
        }
    }
    let mut expanded = Vec::new();
    for call in all.iter().filter(|n| n.kind() == "macro_invocation") {
        let Some(name) = call.child_by_field_name("macro") else {
            continue;
        };
        if !selected.iter().any(|s| s == text(name)) {
            let mut scope = call.parent();
            if scope.is_some_and(|n| n.kind() == "expression_statement") {
                scope = scope.and_then(|n| n.parent());
            }
            if strict
                && scope.is_some_and(|n| n.kind() == "source_file")
                && !ignored.iter().any(|s| s == text(name))
            {
                bail!(
                    "unhandled item-position macro {} at line {}; select it with macros or explicitly exclude it with ignore_macros",
                    text(name),
                    call.start_position().row + 1
                );
            }
            continue;
        }
        let mut scope = call.parent();
        if scope.is_some_and(|n| n.kind() == "expression_statement") {
            scope = scope.and_then(|n| n.parent());
        }
        if scope.is_none_or(|n| n.kind() != "source_file") {
            bail!(
                "selected macro {} invocation must be at file scope",
                text(name)
            );
        }
        let Some((parameters, body)) = templates.get(text(name)) else {
            bail!("selected macro {} has no local definition", text(name));
        };
        let mut cursor = call.walk();
        let arguments = call
            .named_children(&mut cursor)
            .find(|n| n.kind() == "token_tree")
            .unwrap();
        let mut cursor = arguments.walk();
        let values: Vec<_> = arguments.named_children(&mut cursor).collect();
        if values.len() != parameters.len() {
            bail!(
                "selected macro {} argument count does not match",
                text(name)
            );
        }
        let mut residual = text(arguments).to_string();
        for value in values.iter().rev() {
            residual.replace_range(
                value.start_byte() - arguments.start_byte()
                    ..value.end_byte() - arguments.start_byte(),
                "",
            );
        }
        if residual
            .chars()
            .any(|c| !c.is_whitespace() && !matches!(c, '(' | ')' | '[' | ']' | '{' | '}' | ','))
        {
            bail!(
                "selected macro {} has unsupported argument tokens",
                text(name)
            );
        }
        let mut substitutions = BTreeMap::new();
        for ((parameter, kind), value) in parameters.iter().zip(values) {
            let matches = if kind == "ident" {
                value.kind() == "identifier"
            } else {
                matches!(
                    value.kind(),
                    "string_literal"
                        | "raw_string_literal"
                        | "integer_literal"
                        | "float_literal"
                        | "char_literal"
                        | "boolean_literal"
                )
            };
            if !matches {
                bail!(
                    "selected macro {} argument {parameter} is not {kind}",
                    text(name)
                );
            }
            substitutions.insert(parameter.clone(), text(value).to_string());
        }
        let mut changes = Vec::new();
        replacements(*body, source, &substitutions, &mut changes)?;
        let mut output = text(*body).to_string();
        for (start, end, value) in changes.into_iter().rev() {
            output.replace_range(start - body.start_byte()..end - body.start_byte(), &value);
        }
        let output = output[1..output.len() - 1].to_string();
        expanded.push(Expansion {
            source: output,
            line: call.start_position().row + 1,
        });
    }
    Ok(expanded)
}

#[cfg(test)]
mod tests {
    use super::*;
    /// A selected template preserves docs, tuple fields and public methods.
    #[test]
    fn a_template_is_read_by_the_existing_rust_grammar() {
        let source = r#"macro_rules! value { ($name:ident, $doc:literal) => {
            #[doc = $doc] pub struct $name(pub i64);
            impl $name { /// Reads the raw value.
                pub fn raw(self)->i64 { self.0 }
            }
        }; }
        value!(Price,"An exact price.");"#;
        let mut grammar = super::super::grammar("rust", None).unwrap();
        grammar.macros = vec!["value".into()];
        let extracted = grammar.extract(source);
        assert!(extracted.failure.is_none(), "{:?}", extracted.failure);
        assert_eq!(extracted.expansions.len(), 1);
        let price = extracted
            .declarations
            .iter()
            .find(|d| d.name == "Price" && d.kind == "struct")
            .unwrap();
        assert_eq!(price.doc, "An exact price.");
        assert!(extracted.declarations.iter().any(|d| d.name == "raw"));
        assert!(
            extracted
                .declarations
                .iter()
                .any(|d| d.name == "0" && d.kind == "field")
        );
        assert!(
            extracted.expansions[0]
                .source
                .contains("pub struct Price(pub i64)")
        );
    }
    /// Unsupported selected macro rules must never look like an empty success.
    #[test]
    fn a_selected_repetition_is_a_coverage_failure() {
        assert!(
            expand(
                "macro_rules! values { ($($name:ident),*)=>{} } values!(A,B);",
                &["values".into()],
                &[],
                false
            )
            .is_err()
        );
    }
    /// A new declaration macro cannot silently shrink a strict catalog.
    #[test]
    fn strict_macro_coverage_is_explicit_and_ignores_function_expressions() {
        assert!(
            expand("new_api!(Thing);", &[], &[], true)
                .unwrap_err()
                .to_string()
                .contains("unhandled item-position macro new_api")
        );
        assert!(expand("const_assert!(true);", &[], &["const_assert".into()], true).is_ok());
        assert!(expand("pub fn run(){ println!(\"hello\"); }", &[], &[], true).is_ok());
    }
}
